export default function ContactForm() {
  async function saveContactMessage(formData: FormData) {
    'use server'

    const name = formData.get('name')
    const email = formData.get('email')
    const message = formData.get('message')

    // JavaScript validation to check that all fields are provided
    if (
      !name ||
      !email ||
      !message ||
      typeof name !== 'string' ||
      typeof email !== 'string' ||
      typeof message !== 'string' ||
      !name.trim() ||
      !email.trim() ||
      !message.trim()
    ) {
      throw new Error('All fields are required')
    }

    // Simulate saving contact message
    console.log('Saving contact message:', { name, email, message })
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={saveContactMessage}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="Email" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Message" required />
        </div>
        <button type="submit">Submit</button>
      </form>
    </div>
  )
}
